"use client";

import { motion } from "motion/react";
import { useId } from "react";

const BEAM_DURATION = 2.5;
const BEAM_REPEAT_DELAY = 0.8;
const BEAM_COLOR = "#A78BFA";

function BeamGradient({
  id,
  color = BEAM_COLOR,
}: {
  id: string;
  color?: string;
}) {
  return (
    <motion.linearGradient
      id={id}
      gradientUnits="userSpaceOnUse"
      x1="0"
      x2="0"
      initial={{ y1: 200, y2: 240 }}
      animate={{
        y1: [200, -40],
        y2: [240, 0],
      }}
      transition={{
        duration: BEAM_DURATION,
        ease: "linear",
        repeat: Infinity,
        repeatType: "loop",
        repeatDelay: BEAM_REPEAT_DELAY,
      }}
    >
      <stop stopColor={color} stopOpacity="0" />
      <stop offset="32.5%" stopColor={color} />
      <stop stopColor="white" />
      <stop offset="100%" stopColor="white" stopOpacity="0" />
    </motion.linearGradient>
  );
}

function BeamPath({ d, gradientId }: { d: string; gradientId: string }) {
  return (
    <path
      d={d}
      fill="none"
      stroke={`url(#${gradientId})`}
      strokeWidth="1.5"
      strokeLinecap="round"
    />
  );
}

